import * as React from "react"

function HamburgerMenuWithOpencloseAnimation({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="hamburger-menu-with-openclose-animation"
      className={className}
      dangerouslySetInnerHTML={{ __html: "\n<div class=\"min-h-screen bg-gray-100 flex flex-col justify-center\">\n    <div class=\"relative py-3 sm:max-w-xl mx-auto\">\n        <nav x-data=\"{ open: false }\">\n            <button class=\"w-14 h-14 relative focus:outline-none bg-teal-600 rounded\" @click=\"open = !open\">\n                <div class=\"block w-5 absolute left-6 top-1/2   transform  -translate-x-1/2 -translate-y-1/2\">\n                    <span  class=\"block absolute h-0.5 w-7 text-white bg-current transform transition duration-500 ease-in-out\" :class=\"{'rotate-45': open,' -translate-y-1.5': !open }\"></span>\n                    <span  class=\"block absolute  h-0.5 w-5 text-white bg-current   transform transition duration-500 ease-in-out\" :class=\"{'opacity-0': open } \"></span>\n                    <span  class=\"block absolute  h-0.5 w-7 text-white bg-current transform  transition duration-500 ease-in-out\" :class=\"{'-rotate-45': open, ' translate-y-1.5': !open}\"></span>\n                </div>\n            </button>\n        </nav>\n    </div>\n</div>" }}
      {...props}
    />
  )
}

export { HamburgerMenuWithOpencloseAnimation }
